<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { CheckCircle2, Clipboard, CloudDownload, KeyRound, Link2Off, LogOut } from '@lucide/vue'
import { activateLicense, deactivateLicense } from '@/infrastructure/licensing/license-service'
import { copyText } from '@/infrastructure/platform/clipboard'
import { useAppStore } from '@/stores/app-store'
import AppDialog from '@/components/AppDialog.vue'
import ConfirmGraphic from '@/components/ConfirmGraphic.vue'

const store = useAppStore()
const code = ref('')
const busy = ref(false)
const error = ref('')
const deactivateOpen = ref(false)
const activateConfirmOpen = ref(false)
const statusText = computed(() => {
  if (store.license.kind === 'active') return '已激活，可使用全部功能'
  if (store.license.kind === 'expired') return `授权已过期：${store.license.expiresAt}`
  if (store.license.kind === 'invalid') return store.license.reason
  return '尚未激活'
})
const expiryLabel = computed(() => {
  if (store.license.kind !== 'active' || store.license.payload.e === undefined) return '永久有效'
  return `有效期至 ${new Date(store.license.payload.e).toLocaleDateString('zh-CN')}`
})
/** 当前已保存的授权码：激活后展示，方便用户换设备/浏览器时复制重输 */
const savedCode = computed(() => store.settings.licenseCode ?? '')

onMounted(async () => { await store.initialize() })

async function copyLicense(): Promise<void> {
  try {
    await copyText(savedCode.value)
    store.notify('授权码已复制', 'success')
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '复制失败，请长按授权码手动复制', 'error')
  }
}

/** 点击「激活授权码」：先弹联网确认，确认后才走联网激活（2026-09-07 统一联网二次确认） */
function askActivate(): void {
  if (!busy.value && code.value.trim()) activateConfirmOpen.value = true
}

async function activate(): Promise<void> {
  activateConfirmOpen.value = false
  // V1.0.38：设备明确断网时直接 toast，不发请求（onLine=false 一定没网；onLine=true 不一定有网，
  // 后者由 service 层 network 标记兜底，同样走 toast）
  if (navigator.onLine === false) {
    store.notify('当前没有网络连接。激活需要联网，请连接网络（Wi-Fi 或蜂窝数据）后重试。', 'error')
    return
  }
  busy.value = true
  error.value = ''
  try {
    const status = await activateLicense(store.repository, code.value)
    if (status.kind === 'active') {
      await store.refreshLicense()
      // activateLicense 只写了持久层，这里同步内存 settings，否则本会话内「当前授权码」卡片读到旧值（空）
      store.settings = { ...store.settings, licenseCode: code.value.trim() }
      store.notify('授权激活成功', 'success')
      code.value = ''
    } else if (status.kind === 'invalid' && status.network) {
      // 网络不通：toast 强提醒——只显示在按钮上方的小字用户根本注意不到（以为点了没反应）
      store.notify(status.reason, 'error')
    } else {
      error.value = status.kind === 'invalid'
        ? status.reason
        : status.kind === 'expired'
          ? '授权码已超过有效期，请联系作者续期。'
          : '激活失败'
    }
  } catch (cause) {
    // 2026-09-11 修复：activateLicense 内的 IndexedDB/网络等异常如果未被内部 catch 转 invalid 抛出，
    // 这里必须兜底并复位 busy，否则按钮会永远卡在「验证中…」，用户看到「没反应」
    console.error('[activate] 未捕获异常：', cause)
    error.value = cause instanceof Error && cause.message ? `激活失败：${cause.message}` : '激活失败，请稍后重试'
  } finally {
    busy.value = false
  }
}

async function deactivate(): Promise<void> {
  busy.value = true
  try {
    const failure = await deactivateLicense(store.repository)
    if (failure) {
      // 联网解绑失败：保留绑定与弹窗，提示原因
      store.notify(failure, 'error')
      return
    }
    await store.refreshLicense()
    // 同步清掉内存 settings 里的授权码，避免残留显示
    store.settings = { ...store.settings, licenseCode: undefined }
    deactivateOpen.value = false
    store.notify('已清除本机授权码', 'success')
  } catch (cause) {
    // 同 activate：避免异常时 busy 永远卡住
    console.error('[deactivate] 未捕获异常：', cause)
    store.notify(cause instanceof Error && cause.message ? `解绑失败：${cause.message}` : '解绑失败，请稍后重试', 'error')
  } finally {
    busy.value = false
  }
}
</script>

<template>
  <main class="page license-page">
    <section class="card status-card" :class="store.license.kind">
      <CheckCircle2 v-if="store.license.kind === 'active'" :size="36" aria-hidden="true" />
      <KeyRound v-else :size="36" aria-hidden="true" />
      <h2>{{ statusText }}</h2>
      <p v-if="store.license.kind === 'active'">{{ expiryLabel }}。激活后记账数据全程保存在本机。</p>
      <p v-else>激活需联网验证一次，之后可离线使用。</p>
    </section>

    <section v-if="store.license.kind !== 'active'" class="card license-card">
      <label for="license-code" class="field-label">输入授权码</label>
      <textarea id="license-code" v-model="code" class="field code-field" rows="4" autocomplete="off" placeholder="粘贴作者发给你的授权码" />
      <p v-if="error" class="field-error" role="alert">{{ error }}</p>
      <button class="button primary" type="button" :disabled="busy || !code.trim()" @click="askActivate"><KeyRound :size="19" />{{ busy ? '验证中…' : '激活授权码' }}</button>
      <p class="online-hint">激活需要联网，且一个授权码只能绑定一台设备。</p>
    </section>

    <section v-if="savedCode" class="card license-card">
      <h2>{{ store.license.kind === 'active' ? '当前授权码' : '本地保存的授权码' }}</h2>
      <p v-if="store.license.kind === 'active'">本授权码已绑定此设备。换设备时先在此解绑，再到新设备输入此码激活。</p>
      <p v-else>授权状态异常，但本地授权码仍保留。你可以复制保存，或主动解绑清除本机记录。</p>
      <code data-license-code>{{ savedCode }}</code>
      <button class="button secondary" type="button" @click="copyLicense"><Clipboard :size="19" />复制授权码</button>
    </section>

    <button v-if="savedCode" class="button danger deactivate" type="button" @click="deactivateOpen = true"><LogOut :size="19" />解绑当前授权码</button>

    <p class="web-warning">更换浏览器或清除浏览器数据后授权状态会丢失；同一授权码只能激活一台设备，换设备时可在原设备解绑后重新激活。</p>
  </main>

  <AppDialog :open="activateConfirmOpen" title="激活需要联网" position="center" @close="activateConfirmOpen = false">
    <ConfirmGraphic :icon="CloudDownload" strong="联网验证并绑定此设备" sub="仅上传授权码与设备标识，不上传任何账单数据；激活成功后即可离线使用" />
    <template #actions>
      <button class="button secondary equal-action" type="button" @click="activateConfirmOpen = false">取消</button>
      <button class="button primary equal-action" type="button" :disabled="busy" @click="activate">{{ busy ? '验证中…' : '确认联网' }}</button>
    </template>
  </AppDialog>

  <AppDialog :open="deactivateOpen" title="确认解绑授权码" position="center" @close="deactivateOpen = false">
    <ConfirmGraphic :icon="Link2Off" tone="danger" strong="解绑后无法记账" sub="已有账单与备份不会被删除，再次激活后可继续使用；解绑需联网，成功后可在新设备重新激活" />
    <template #actions>
      <button class="button secondary equal-action" type="button" @click="deactivateOpen = false">取消</button>
      <button class="button danger equal-action" type="button" :disabled="busy" @click="deactivate">{{ busy ? '解绑中…' : '确认解绑' }}</button>
    </template>
  </AppDialog>
</template>

<style scoped>
.license-page { display: grid; gap: 16px; }
.status-card, .license-card { display: grid; gap: 10px; padding: 18px 16px; }
.status-card { place-items: center; color: var(--color-text-secondary); text-align: center; }
.status-card.active { color: var(--color-income); }
.status-card h2 { margin: 0; color: var(--color-text); font-size: 16px; }
.status-card p, .license-card p { margin: 0; color: var(--color-text-secondary); }
/* V1.0.38 修复：上一行 .license-card p（灰）+ scoped 属性的优先级高于全局 .field-error（红），
   激活失败理由一直被盖成灰色，这里显式改回红色 */
.license-card p.field-error { color: var(--color-danger); }
.license-card h2 { margin: 0; font-size: 16px; }
.license-card code { padding: 12px; border-radius: 10px; background: var(--color-surface-muted); overflow-wrap: anywhere; color: var(--color-text); font-size: 13px; }
.code-field { min-height: 110px; resize: vertical; }
.online-hint { margin: 0; color: var(--color-text-secondary); font-size: 13px; }
.deactivate { width: 100%; }
.web-warning { margin: 0; color: var(--color-text-secondary); font-size: 13px; }
/* 居中弹窗底部两按钮等宽 */
.equal-action { flex: 1; }
</style>
